const fs = require("fs");
const path = require("path");
const {withAppDelegate, withXcodeProject} = require("@expo/config-plugins");

/**
 * Ensures the iOS project always embeds a JS bundle (`main.jsbundle`) inside the
 * `.app` even in Debug builds, and updates `AppDelegate.swift` to load the
 * embedded bundle first when available so Xcode ⌘R works without Metro running.
 * Also syncs `MARKETING_VERSION` and `CURRENT_PROJECT_VERSION` in pbxproj and
 * generates a shared `stoic-Release` Xcode scheme for one-click Release testing.
 */
const withEmbeddedJsBundle = (config) => {
    config = withXcodeProject(config, (config) => {
        const pbxProject = config.modResults;
        const iosRoot = config.modRequest.platformProjectRoot;
        const appVersion = config.version || "3.0.0";
        const buildNumber = config.ios?.buildNumber || "33";

        // 1. Patch the "Bundle React Native code and images" shell script phase directly in pbxproj
        // so Debug builds always run `expo export:embed` and embed `main.jsbundle`.
        const shellPhases = pbxProject.hash.project.objects.PBXShellScriptBuildPhase || {};
        for (const key of Object.keys(shellPhases)) {
            const phase = shellPhases[key];
            if (
                phase &&
                typeof phase === "object" &&
                phase.name &&
                phase.name.includes("Bundle React Native code and images") &&
                typeof phase.shellScript === "string"
            ) {
                phase.shellScript = phase.shellScript.replace(
                    "export SKIP_BUNDLING=1",
                    "unset SKIP_BUNDLING\\n  export FORCE_BUNDLING=1"
                );
            }
        }

        // 2. Sync MARKETING_VERSION and CURRENT_PROJECT_VERSION across all target build configurations
        const buildConfigs = pbxProject.hash.project.objects.XCBuildConfiguration || {};
        for (const key of Object.keys(buildConfigs)) {
            const cfg = buildConfigs[key];
            if (cfg && typeof cfg === "object" && cfg.buildSettings) {
                if (cfg.buildSettings.MARKETING_VERSION !== undefined) {
                    cfg.buildSettings.MARKETING_VERSION = appVersion;
                }
                if (cfg.buildSettings.CURRENT_PROJECT_VERSION !== undefined) {
                    cfg.buildSettings.CURRENT_PROJECT_VERSION = buildNumber;
                }
            }
        }

        // 3. Also write ios/.xcode.env.updates and duplicate shared scheme as stoic-Release.xcscheme
        try {
            const envUpdatesPath = path.join(iosRoot, ".xcode.env.updates");
            fs.writeFileSync(
                envUpdatesPath,
                [
                    "# Generated by plugins/withEmbeddedJsBundle.js — embeds the JS bundle in every configuration (no Metro).",
                    "unset SKIP_BUNDLING",
                    "export FORCE_BUNDLING=1",
                    "",
                ].join("\n"),
                "utf8"
            );

            const schemesDir = path.join(
                iosRoot,
                `${config.modRequest.projectName}.xcodeproj`,
                "xcshareddata",
                "xcschemes"
            );
            const debugSchemePath = path.join(
                schemesDir,
                `${config.modRequest.projectName}.xcscheme`
            );
            const releaseSchemePath = path.join(
                schemesDir,
                `${config.modRequest.projectName}-Release.xcscheme`
            );
            if (fs.existsSync(debugSchemePath)) {
                const schemeXml = fs
                    .readFileSync(debugSchemePath, "utf8")
                    .replace(
                        /buildConfiguration\s*=\s*"Debug"/g,
                        'buildConfiguration = "Release"'
                    );
                fs.writeFileSync(releaseSchemePath, schemeXml, "utf8");
            }
        } catch {
            // Non-fatal
        }

        return config;
    });

    // 4. Patch AppDelegate.swift bundleURL() so #if DEBUG prefers embedded main.jsbundle
    config = withAppDelegate(config, (config) => {
        if (config.modResults.language !== "swift") {
            return config;
        }

        const marker = 'Bundle.main.url(forResource: "main", withExtension: "jsbundle")';
        const debugBlockRegex =
            /#if DEBUG\s+return RCTBundleURLProvider\.sharedSettings\(\)\.jsBundleURL\(forBundleRoot:\s*"\.expo\/\.virtual-metro-entry"\)\s+#else/;

        if (debugBlockRegex.test(config.modResults.contents)) {
            config.modResults.contents = config.modResults.contents.replace(
                debugBlockRegex,
                [
                    "#if DEBUG",
                    `    if let embedded = ${marker} {`,
                    "      return embedded",
                    "    }",
                    '    return RCTBundleURLProvider.sharedSettings().jsBundleURL(forBundleRoot: ".expo/.virtual-metro-entry")',
                    "#else",
                ].join("\n")
            );
        }

        return config;
    });

    return config;
};

module.exports = withEmbeddedJsBundle;
